; lost.asm -- chapter 12: a routine that pushes and does not pop
; generated by gen12.py
        INCLUDE "msx.inc"
        OUTPUT "lost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
; A routine that pushes a pair and returns without popping it.
init:   di
        ld sp, SYS_AREA         ; the stack below the BIOS's work area
        ld bc, lost
        call keep
back:   jr back                 ; where the program should come back to
stop:   jr stop

keep:   push bc                 ; kept for later, and never taken back
        ret                     ; RET takes BC for the way back

lost:   jr lost                 ; where the program ends up
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
